SELECT 'application_quizz_version' AS label,MAX(version) AS version FROM quizz.flyway_schema_history; SELECT rules_version,COUNT(*) AS historical_games FROM quizz_task15_experiment.game_session WHERE id<=51 GROUP BY rules_version; SELECT COUNT(*) AS historical_decision_5000 FROM quizz_task15_experiment.game_session WHERE id<=51 AND JSON_EXTRACT(config_snapshot,'$.decisionDurationMs')=5000;
